import {mkdirSync, writeFileSync} from 'node:fs'
import {dirname} from 'node:path'
import minimist from 'minimist'
import {availableLocales} from '@formatjs_generated/cldr.supported-locales/default-content.js'

interface Args extends minimist.ParsedArgs {
  out: string
}
function main(args: Args): void {
  if (!args.out) throw new Error('--out required')
  const locales = Array.from(availableLocales).sort()
  mkdirSync(dirname(args.out), {recursive: true})
  writeFileSync(
    args.out,
    '// Generated by //crates/intl_segmenter:data. Do not edit.\n' +
      'pub static AVAILABLE_LOCALES: &[&str] = &[\n' +
      locales.map(locale => '    ' + JSON.stringify(locale) + ',').join('\n') +
      '\n];\n'
  )
}
if (import.meta.filename === process.argv[1])
  main(minimist(process.argv.slice(2)) as Args)
